'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function initIntroSplash(){const splash=$('#intro-splash');if(!splash)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const started=performance.now();let finished=false;const close=()=>{if(finished)return;finished=true;const wait=Math.max(0,(reduced?900:2350)-(performance.now()-started));window.setTimeout(()=>{document.body.classList.add('site-ready');if(reduced){splash.remove();return}splash.classList.add('is-leaving');window.setTimeout(()=>splash.remove(),950)},wait)};window.addEventListener('load',close,{once:true});window.setTimeout(close,3500)}
