const slides=[{title:'Şuurlu Gençlik<br><em>Güçlü Türkiye</em>',desc:'Ahlak, ilim ve sorumluluk bilinciyle ülkemizin yarınlarını inşa eden bir gençlik için çalışıyoruz.',caption:'ÖNCE AHLAK VE MANEVİYAT'},{title:'Birlikte Öğrenen,<br><em>Birlikte Üreten</em>',desc:'Gençlerin kendini geliştirdiği, fikirlerini paylaştığı ve toplum için sorumluluk aldığı çalışmalar yürütüyoruz.',caption:'İMAN · ŞUUR · EMEK'},{title:'Köklerinden Güç Alan,<br><em>Geleceğe Yürüyen</em>',desc:'Kültürümüzden aldığımız güçle, ilim ve kardeşlik etrafında yeni nesiller için çalışıyoruz.',caption:'AYNI İDEAL, AYNI HEYECAN'},{title:'Ahlaklı, İlimli,<br><em>Sorumluluk Sahibi</em>',desc:'Önce ahlak ve maneviyat anlayışıyla güçlü bir gençliğin ve güçlü bir Türkiye’nin yanında duruyoruz.',caption:'GELECEĞE BİRLİKTE'}];
let slide=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,timer;
$('#dots').innerHTML=slides.map((_,i)=>`<button aria-label="${i+1}. slayt" data-slide="${i}"></button>`).join('');
function renderSlide(){const s=slides[slide];$('#slide-title').innerHTML=s.title;$('#slide-desc').textContent=s.desc;$('.photo-caption').innerHTML=s.caption;$('#slide-count').textContent=`0${slide+1} / 04`;$$('[data-slide]').forEach((b,i)=>{b.classList.toggle('active',i===slide);b.setAttribute('aria-pressed',i===slide)});$('#pause').textContent=paused?'▷':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Slaytları oynat':'Slaytları duraklat')}
function schedule(){clearInterval(timer);if(!paused)timer=setInterval(()=>{if(!dialog.open&&!document.hidden){slide=(slide+1)%slides.length;renderSlide()}},7000)}
function changeSlide(n){slide=(n+slides.length)%slides.length;renderSlide();schedule()}
$('#prev').onclick=()=>changeSlide(slide-1);$('#next').onclick=()=>changeSlide(slide+1);$$('[data-slide]').forEach(b=>b.onclick=()=>changeSlide(Number(b.dataset.slide)));$('#pause').onclick=()=>{paused=!paused;renderSlide();schedule()};renderSlide();schedule();
