function selectCity(id,scroll=false){const b=data.branches.find(x=>x.id===id);if(!b)return;currentCity=id;$('#city-select').value=id;$('#map-label').textContent=b.city;$$('#turkiye > g').forEach(g=>{const selected=(g.id==='istanbul-asya'?'istanbul-avrupa':g.id)===id;g.classList.toggle('selected',selected);g.setAttribute('aria-pressed',selected)});$('#branch-info').innerHTML=`<div class="branch-code">${esc(b.code)}</div><h3>${esc(b.city)}</h3><p>İl Teşkilatı</p>${imageURL(b.photo)?`<img class="branch-photo" src="${esc(imageURL(b.photo))}" alt="${esc(b.name||b.city+' İl Başkanı')}">`:''}<div class="detail-line"><small>İL BAŞKANI</small>${esc(b.name||'Bilgi henüz eklenmedi')}</div><div class="detail-line"><small>ADRES</small>${esc(b.address||'Adres bilgisi henüz eklenmedi')}</div><div class="detail-line"><small>TELEFON</small>${b.phone?`<a href="tel:${esc(b.phone.replace(/[^+\d]/g,''))}">${esc(b.phone)}</a>`:'Telefon bilgisi henüz eklenmedi'}</div>${b.address?`<a class="text-button" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(b.address)}" target="_blank" rel="noopener">Yol tarifi al ↗</a>`:''}`;if(scroll)$('#subeler').scrollIntoView({behavior:'smooth'})}
function management(tab){currentTab=tab;$$('.tabs [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)});const el=$('#management-content');if(tab==='president'){el.innerHTML=`<div class="president">${portrait(data.president)}<div class="president-copy"><p class="eyebrow">GENEL BAŞKAN</p><h3>${esc(data.president.name||'Genel Başkanımız')}</h3><p>${esc(data.president.bio||'Genel başkanın fotoğrafı, özgeçmişi ve mesajı bu alanda yer alacaktır.')}</p><button class="text-button" id="president-detail">Başkanın mesajı ↗</button></div></div>`;$('#president-detail').onclick=()=>openDialog(`<p class="eyebrow">GENEL BAŞKAN</p><h2>${esc(data.president.name||'Genel Başkanımız')}</h2><p>${esc(data.president.bio||'Başkanın özgeçmişi ve mesajı henüz eklenmedi.')}</p>`)}else if(tab==='board'){el.innerHTML=`<div class="board-grid">${data.board.map(p=>`<button class="person-card" data-person="${p.id}">${portrait(p)}<div class="person-text"><h3>${esc(p.name||p.title+' Başkanlığı')}</h3><p>${esc(p.name?p.title+' Başkanı':'İsim bilgisi eklenecek')}</p><span>↗</span></div></button>`).join('')}</div>`;$$('[data-person]').forEach(b=>b.onclick=()=>personDetail(Number(b.dataset.person)))}else{el.innerHTML='<input class="search" id="branch-search" aria-label="Şube başkanları arasında il ara" placeholder="İl adıyla arayın…"><div class="branch-list" id="branch-list"></div>';function list(q=''){$('#branch-list').innerHTML=data.branches.filter(b=>b.city.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr'))).map(b=>`<button data-branch="${b.id}">${esc(b.city)}<small>${esc(b.name||'Başkan bilgisi eklenecek')}</small></button>`).join('')||'<p>Aramanıza uygun il bulunamadı.</p>';$$('[data-branch]').forEach(b=>b.onclick=()=>selectCity(b.dataset.branch,true))}list();$('#branch-search').oninput=e=>list(e.target.value)}}
function personDetail(id){const p=data.board.find(p=>p.id===id);if(!p)return;openDialog(`<p class="eyebrow">BAŞKANLIK DİVANI</p><h2>${esc(p.name||p.title+' Başkanlığı')}</h2><p>${esc(p.title)} ${p.name?'Başkanı':''}</p><p>${esc(p.bio||'Özgeçmiş bilgisi henüz eklenmedi.')}</p><h3>Başkan Yardımcıları</h3>${p.assistants.length?p.assistants.map(a=>`<div class="assistant-card">${imageURL(a.photo)?`<img src="${esc(imageURL(a.photo))}" alt="${esc(a.name)}">`:''}<div><b>${esc(a.name)}</b><small>${esc(a.title||'Başkan Yardımcısı')}</small></div></div>`).join(''):'<p>Bu başkanlığa bağlı başkan yardımcıları henüz eklenmedi.</p>'}`)}
